# Тексерістер: кілт, нұсқа саны, дәлелдің мәтінде бар екені
import re
for x in Q:
    assert x["key"] in "ABCD" and len(x["options"]) == 4
    assert set(x["distractor_notes"]) == set("ABCD") - {x["key"]}, x["id"]
    body = " ".join(next(t for t in texts if t["id"] == x["text_id"])["paragraphs"]).replace("**", "")
    for e in x["evidence"] + [e for v in x["distractor_evidence"].values() for e in v]:
        e2 = re.sub(r"\s*\([^)]*(азатжол|бөлім)[^)]*\)$", "", e)
        for frag in [f.strip(" .") for f in e2.split("...")]:
            if frag and frag not in body: print("ДӘЛЕЛ ТАБЫЛМАДЫ:", x["id"], "|", frag)

bank = {"bank_id": "kaz-L2-nis-sample-v1", "track": "second_language",
        "source": "НЗМ 7-сыныпқа конкурстық іріктеудің тест үлгілері, «Қазақ тілі (екінші тіл)», 21–40",
        "skills": SKILLS, "evidence_ru": EVID_RU, "style_notes": [], "texts": texts, "items": Q}
(OUT / "bank_l2_v1.json").write_text(json.dumps(bank, ensure_ascii=False, indent=2), encoding="utf-8")
from collections import Counter
print("items", len(Q), "keys", Counter(x["key"] for x in Q), "skills", Counter(x["skill"][0] for x in Q), "levels", Counter(x["level"] for x in Q))

# Мұғалімге арналған тексеру құжаты
md = ["# Қазақ тілі (екінші тіл) – 1-нұсқа: тапсырмалар банкі", "",
      "Бағыт: **екінші тіл** (орыс сыныптары). Дереккөз: " + bank["source"] + ".", ""]
for t in texts:
    md += [f"## {t['id'].split('-t')[1]}-мәтін" + (f": {t['title']}" if t["title"] else ""), ""]
    for i, p in enumerate(t["paragraphs"], 1):
        md += [(f"{i}. " if t["numbered_paragraphs"] else "") + p.replace("**", "") , ""]
    for x in [x for x in Q if x["text_id"] == t["id"]]:
        md += [f"### {x['number']}. " + x["stem"].replace("\n", "  \n"), ""]
        md += [f"- **{k})** {v}" + ("  ✅" if k == x["key"] else "") for k, v in x["options"].items()]
        md += ["", f"*Дағды:* {x['skill']} – {x['skill_name']} · *Деңгей:* {x['level']}", "", "**Мәтіндегі дәлел:**"]
        md += [f"> {e}" for e in x["evidence"]]
        md += ["", f"**Түсініктеме:** {x['explanation']}", f"*Орысша:* {x['explanation_ru']}", "", "**Қалған нұсқалар неге қате:**"]
        for k in sorted(x["distractor_notes"]):
            v = x["distractor_notes"][k]; ev = x["distractor_evidence"][k]
            md.append(f"- {k}) {v[:1].upper()+v[1:]}" + (" Дәлел: «" + "», «".join(ev) + "»" if ev else ""))
            md.append(f"  - *Орысша:* {x['distractor_notes_ru'][k]}")
        md += ["", "---", ""]
(OUT.parent / "docs" / "l2-1-nusqa-tekseru.md").write_text("\n".join(md), encoding="utf-8")
